import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Configuration reference","description":"","frontmatter":{"pageId":"admins/configuration","contentRevision":6},"headers":[],"relativePath":"en/admins/configuration.md","filePath":"en/admins/configuration.md"}'),r={name:"en/admins/configuration.md"};function a(n,e,i,s,l,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="configuration-reference" tabindex="-1">Configuration reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration reference&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Settings bind to root JSON sections. Environment overrides replace colons with double underscores and add Rimlink__: for example Rimlink__Server__Port=25560 and Rimlink__Auth__AdminLogins__0=admin. Arrays use numeric indices, not comma-separated strings.</p><p>Set the service/container environment and restart after changes: this guide does not promise hot reload. The table below records Options initializers, not a sample populated with secrets. deploy/appsettings.example.json is a useful template but not an exhaustive contract (SelfSignedPath, for example, is absent).</p><p>The complete key inventory follows below. Read the setting, not just its suffix: Hygiene:ArchiveAfterDays counts real days of absence, Hygiene:ArchiveMaxColonyDays counts colony game days, and NewbieProtectionDays counts real days since the first save. Ticks means game ticks and Bytes means bytes. Preserve units when transferring settings.</p><h2 id="config-method" tabindex="-1">How do I change settings without guessing units? <a class="header-anchor" href="#config-method" aria-label="Permalink to &quot;How do I change settings without guessing units? {#config-method}&quot;">​</a></h2><p>Find the exact key and its group explanation. JSON uses Section/Key; environment variables use Rimlink__Section__Key, with array indices. Preserve working settings and test one related change set on a test server. Options validation may refuse startup: fix its named value, not the database.</p><p>Examples are not exhaustive: the table is checked against Options classes, while mechanic constants are separate. Zero does not universally mean disabled: Backup:IntervalHours=0 disables scheduling, other fields differ. Do not promise behavior from Raids:TimeoutDays; it is declared but the current client uses a constant.</p><p>Verify behavior and the redacted /api/admin/config after applying changes. Redaction is not a reason to dump the full environment into tickets.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Admin:ApiToken, Admin:Tokens:*:Token, Auth:SteamWebApiKey and Server:ServerPassword are secrets. FeedBufferSize: 100–100000, FeedPingSeconds: 1–300; gift/trade lifetimes and MaxOpenTrades must be &gt;=1. Integrity thresholds are nonnegative; Freeze must not be below Warn except 0. Hygiene requires a 1–168-hour sweep, nonnegative age/wealth values (0 disables the corresponding filter; ArchiveAfterDays=0 disables archiving) and 4 strictly increasing tiers. Incident catalogs require unique IDs, valid Kind and positive multipliers; a nonempty list replaces the entire built-in catalog.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./security-auth">TLS, authentication and permissions</a></li><li><a href="./gameplay-policy">Server gameplay policy</a></li></ul><h2 id="reference" tabindex="-1">All bindable keys <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;All bindable keys {#reference}&quot;">​</a></h2><p>This table follows Options declarations, not the sample JSON. <code>null</code> means unset; <code>&quot;&quot;</code> is an empty string; <code>[]</code> is an empty array. <code>Protocol.Limits.*</code> refers to protocol constants: MaxParcelBytes = 921600, MaxItemsPerParcel = 200, MaxPawnsPerParcel = 10. Replace <code>*</code> with a zero-based index.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Initial default</th></tr></thead><tbody><tr><td><code>Panel:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Panel:Public</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Panel:PublicPlayerNames</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Panel:SessionHours</code></td><td><code>int</code></td><td><code>12</code></td></tr><tr><td><code>Panel:ServerName</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Panel:Description</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Panel:PublicAddress</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Server:Port</code></td><td><code>int</code></td><td><code>25560</code></td></tr><tr><td><code>Server:DataDir</code></td><td><code>string</code></td><td><code>&quot;./data&quot;</code></td></tr><tr><td><code>Server:MaxPlayers</code></td><td><code>int</code></td><td><code>50</code></td></tr><tr><td><code>Server:ServerPassword</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Server:MaxSettlementsPerPlayer</code></td><td><code>int</code></td><td><code>1</code></td></tr><tr><td><code>Tls:Required</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Tls:CertificatePath</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Tls:KeyPath</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Tls:SelfSignedPath</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Auth:AllowPassword</code></td><td><code>bool</code></td><td><code>false</code></td></tr><tr><td><code>Auth:SteamWebApiKey</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Auth:AdminSteamIds</code></td><td><code>long[]</code></td><td><code>[]</code></td></tr><tr><td><code>Auth:AdminLogins</code></td><td><code>string[]</code></td><td><code>[]</code></td></tr><tr><td><code>Economy:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Economy:MaxParcelBytes</code></td><td><code>int</code></td><td><code>Protocol.Limits.EconomyMaxParcelBytes</code></td></tr><tr><td><code>Economy:MaxItemsPerParcel</code></td><td><code>int</code></td><td><code>Protocol.Limits.EconomyMaxItemsPerParcel</code></td></tr><tr><td><code>Economy:MaxPawnsPerParcel</code></td><td><code>int</code></td><td><code>Protocol.Limits.EconomyMaxPawnsPerParcel</code></td></tr><tr><td><code>Economy:MaxLotsPerPlayer</code></td><td><code>int</code></td><td><code>20</code></td></tr><tr><td><code>Economy:MaxPendingParcels</code></td><td><code>int</code></td><td><code>50</code></td></tr><tr><td><code>Economy:LotLifetimeDays</code></td><td><code>int</code></td><td><code>30</code></td></tr><tr><td><code>Economy:MarketFeePercent</code></td><td><code>int</code></td><td><code>0</code></td></tr><tr><td><code>Economy:SendCooldownSeconds</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Economy:GiftDecisionDays</code></td><td><code>int</code></td><td><code>7</code></td></tr><tr><td><code>Economy:TradeLifetimeDays</code></td><td><code>int</code></td><td><code>7</code></td></tr><tr><td><code>Economy:MaxOpenTrades</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Economy:ServerWealthPercent</code></td><td><code>int</code></td><td><code>100</code></td></tr><tr><td><code>Economy:BlockOutflowUnderThreat</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Economy:StorageFeePercentPerDay</code></td><td><code>double</code></td><td><code>0.5</code></td></tr><tr><td><code>Economy:StorageFreeDays</code></td><td><code>double</code></td><td><code>3</code></td></tr><tr><td><code>Social:MaxBlocks</code></td><td><code>int</code></td><td><code>200</code></td></tr><tr><td><code>Raids:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Raids:MaxRaiders</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Raids:MaxActiveRaidsPerAttacker</code></td><td><code>int</code></td><td><code>1</code></td></tr><tr><td><code>Raids:TargetCooldownHours</code></td><td><code>int</code></td><td><code>8</code></td></tr><tr><td><code>Raids:PairCooldownHours</code></td><td><code>int</code></td><td><code>24</code></td></tr><tr><td><code>Raids:NewbieProtectionDays</code></td><td><code>int</code></td><td><code>3</code></td></tr><tr><td><code>Raids:MinColonyWealth</code></td><td><code>long</code></td><td><code>20000</code></td></tr><tr><td><code>Raids:LootCapPercent</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Raids:LootCapSilver</code></td><td><code>long</code></td><td><code>5000</code></td></tr><tr><td><code>Raids:AllowKidnap</code></td><td><code>bool</code></td><td><code>false</code></td></tr><tr><td><code>Raids:WarnTicks</code></td><td><code>int</code></td><td><code>60000</code></td></tr><tr><td><code>Raids:TimeoutDays</code></td><td><code>int</code></td><td><code>3</code></td></tr><tr><td><code>Raids:ExpireRealDays</code></td><td><code>int</code></td><td><code>7</code></td></tr><tr><td><code>Raids:PeacefulOffDelayHours</code></td><td><code>int</code></td><td><code>24</code></td></tr><tr><td><code>Raids:VisitHours</code></td><td><code>int</code></td><td><code>12</code></td></tr><tr><td><code>Live:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Live:InviteSeconds</code></td><td><code>int</code></td><td><code>60</code></td></tr><tr><td><code>Live:ReconnectWaitMinutes</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Live:GuestPauses</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Live:GuestPauseSeconds</code></td><td><code>int</code></td><td><code>60</code></td></tr><tr><td><code>Live:MaxFrameBytes</code></td><td><code>int</code></td><td><code>262144</code></td></tr><tr><td><code>Live:DeltasPerSecond</code></td><td><code>int</code></td><td><code>20</code></td></tr><tr><td><code>Live:OrdersPerSecond</code></td><td><code>int</code></td><td><code>30</code></td></tr><tr><td><code>Live:HeartbeatTimeoutSeconds</code></td><td><code>int</code></td><td><code>10</code></td></tr><tr><td><code>Live:SweepSeconds</code></td><td><code>int</code></td><td><code>5</code></td></tr><tr><td><code>Admin:ApiToken</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Admin:Tokens</code></td><td><code>List&lt;ApiTokenOptions&gt;</code></td><td><code>[]</code></td></tr><tr><td><code>Admin:FeedBufferSize</code></td><td><code>int</code></td><td><code>1000</code></td></tr><tr><td><code>Admin:FeedPingSeconds</code></td><td><code>int</code></td><td><code>15</code></td></tr><tr><td><code>Admin:Tokens:*:Name</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Admin:Tokens:*:Token</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Admin:Tokens:*:Scopes</code></td><td><code>string[]</code></td><td><code>[]</code></td></tr><tr><td><code>Integrity:DevMode</code></td><td><code>DevModePolicy</code></td><td><code>DevModePolicy.AdminsOnly</code></td></tr><tr><td><code>Integrity:WealthWarnPerDay</code></td><td><code>long</code></td><td><code>20000</code></td></tr><tr><td><code>Integrity:WealthFreezePerDay</code></td><td><code>long</code></td><td><code>100000</code></td></tr><tr><td><code>Integrity:StorytellerPolicy</code></td><td><code>StorytellerPolicy</code></td><td><code>StorytellerPolicy.Locked</code></td></tr><tr><td><code>Hygiene:ArchiveAfterDays</code></td><td><code>int</code></td><td><code>14</code></td></tr><tr><td><code>Hygiene:ArchiveMaxWealth</code></td><td><code>long</code></td><td><code>100000</code></td></tr><tr><td><code>Hygiene:ArchiveMaxColonyDays</code></td><td><code>int</code></td><td><code>60</code></td></tr><tr><td><code>Hygiene:SweepHours</code></td><td><code>int</code></td><td><code>6</code></td></tr><tr><td><code>Hygiene:WealthTiers</code></td><td><code>long[]?</code></td><td><code>null</code></td></tr><tr><td><code>Incidents:Enabled</code></td><td><code>bool</code></td><td><code>true</code></td></tr><tr><td><code>Incidents:MaxQueuedPerTarget</code></td><td><code>int</code></td><td><code>2</code></td></tr><tr><td><code>Incidents:BasePrice</code></td><td><code>double</code></td><td><code>100</code></td></tr><tr><td><code>Incidents:MinPrice</code></td><td><code>long</code></td><td><code>50</code></td></tr><tr><td><code>Incidents:WarnTicks</code></td><td><code>long</code></td><td><code>30000</code></td></tr><tr><td><code>Incidents:WarnFromLevel</code></td><td><code>int</code></td><td><code>3</code></td></tr><tr><td><code>Incidents:KindCooldownHours</code></td><td><code>double</code></td><td><code>1</code></td></tr><tr><td><code>Incidents:ExpireRealDays</code></td><td><code>double</code></td><td><code>7</code></td></tr><tr><td><code>Incidents:Catalog</code></td><td><code>List&lt;IncidentCatalogEntry&gt;</code></td><td><code>[]</code></td></tr><tr><td><code>Incidents:Catalog:*:Id</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Incidents:Catalog:*:IncidentDef</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Incidents:Catalog:*:FactionDef</code></td><td><code>string?</code></td><td><code>null</code></td></tr><tr><td><code>Incidents:Catalog:*:Kind</code></td><td><code>string</code></td><td><code>&quot;Hostile&quot;</code></td></tr><tr><td><code>Incidents:Catalog:*:PriceMultiplier</code></td><td><code>double</code></td><td><code>1</code></td></tr><tr><td><code>Incidents:Catalog:*:PodsMultiplier</code></td><td><code>double?</code></td><td><code>null</code></td></tr><tr><td><code>Saves:CompactOldVersions</code></td><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p><code>Tls:SelfSignedPath=null</code> selects <code>&lt;DataDir&gt;/tls/server.pfx</code>. <code>Hygiene:WealthTiers=null</code> selects <code>[50000,150000,400000,1000000]</code>. Empty Panel:ServerName displays Rimlink; SessionHours is clamped to 1–168; Description is trimmed to 1000 characters. <code>Saves:CompactOldVersions=false</code> stops new delta creation without deleting existing deltas. <code>Server:ProtocolVersion</code> is derived, not configuration.</p><h3 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>Backup:IntervalHours</code></td><td><code>int</code></td><td><code>24</code></td></tr><tr><td><code>Backup:Keep</code></td><td><code>int</code></td><td><code>7</code></td></tr></tbody></table><p>IntervalHours &lt;= 0 disables scheduling; Keep retains at least one newest archive. Manual backup does not replace a restore test.</p><h3 id="section-semantics" tabindex="-1">Section semantics <a class="header-anchor" href="#section-semantics" aria-label="Permalink to &quot;Section semantics&quot;">​</a></h3><p>Server controls port, storage, capacity and shared server password, not an account password. Tls selects a PEM certificate/key pair or a persisted self-signed certificate. Auth allows password login and promotes Steam IDs/logins; SteamWebApiKey verifies Steam tickets.</p><p>Economy enables exchange and limits parcels (total bytes/items/pawns), lots/pending deliveries, lifetime, market fee and send rate. GiftDecisionDays and TradeLifetimeDays return escrow when a decision/trade expires. ServerWealthPercent includes server assets in wealth, BlockOutflowUnderThreat blocks outflow under threat; StorageFeePercentPerDay charges pawns/perishables after StorageFreeDays. Social:MaxBlocks caps a personal block list.</p><p>Raids controls availability, attacker/active-raid counts, target/pair cooldowns, newcomer protection and minimum wealth. LootCapPercent and LootCapSilver cap loot; AllowKidnap controls kidnapping; WarnTicks is an in-game warning, TimeoutDays is declared but not wired into behavior: the current client uses a constant 3 × 60000 game ticks, ExpireRealDays a real-time expiry, PeacefulOffDelayHours a delay leaving peaceful mode, VisitHours a visit expiry.</p><p>Live sets invite/reconnect waits, guest pause budget, frame bytes, delta/order rates and stream-silence detection. Admin configures the legacy panel token and named token/scopes, SSE replay capacity and ping interval. Integrity controls dev mode, wealth jumps and storyteller; 0 disables the corresponding threshold. Hygiene archives only colonies meeting absence/age/wealth criteria; 0 removes its filter (ArchiveAfterDays=0 disables the sweep).</p><p>Incidents enables paid events, per-target queue, BasePrice/MinPrice, warning from WarnFromLevel, cooldown by Kind and expiry. Catalog:* defines Id, IncidentDef, optional FactionDef, Kind (Hostile/Weather/Kind), PriceMultiplier and optional PodsMultiplier. Do not promise a def from an absent mod.</p><h3 id="outposts-—-pending" tabindex="-1">Outposts — Pending <a class="header-anchor" href="#outposts-—-pending" aria-label="Permalink to &quot;Outposts — Pending&quot;">​</a></h3><p>Enabled defaults to false and cannot replace acceptance qualification. AnchorDirectory must be outside replaceable data trees; sqlite-local-v1 requires the qualified local backend. Linux requires actually qualified ext4/xfs/btrfs and Windows fixed NTFS. Secrets or runtime flags cannot select IsolatedAcceptance or Qualified. <a href="./passive-outposts">Details</a>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>Outposts:Enabled</code></td><td><code>bool</code></td><td><code>false</code></td></tr><tr><td><code>Outposts:AnchorDirectory</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Outposts:StorageContract</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr><tr><td><code>Outposts:QualifiedLinuxFileSystem</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table>',30)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
